const body = $input.first().json.body || $input.first().json;
const email = (body.email || '').trim().toLowerCase();
const password = (body.password || '').trim();

if (!email || !password) {
  return [{ json: { _error: true, message: 'Email and password are required' } }];
}

return [{ json: { email, password } }];

const crypto = require('crypto');

const response = $input.first().json;
const records = response.records || [];

if (records.length === 0) {
  return [{ json: { _auth_error: true, message: 'Invalid email or password' } }];
}

const user = records[0];
const fields = user.fields || {};

// Get stored password value — support both field names
const storedValue = fields.password_hash || fields.password || '';
const inputPassword = $('Extract Credentials').first().json.password;

// Verify password
let passwordValid = false;
if (storedValue.includes(':')) {
  // New format: salt:hash (SHA-256)
  const [salt, hash] = storedValue.split(':');
  const inputHash = crypto.createHash('sha256').update(salt + inputPassword).digest('hex');
  passwordValid = (inputHash === hash);
} else {
  // Legacy plaintext — compare directly but flag for migration
  passwordValid = (storedValue === inputPassword);
  // TODO: Could auto-migrate here by hashing and updating the record
}

if (!passwordValid) {
  return [{ json: { _auth_error: true, message: 'Invalid email or password' } }];
}

// Generate HMAC-SHA256 JWT token
const JWT_SECRET = 'cosmisk-jwt-secret-2026-v1';

const header = Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })).toString('base64url');
const payload = Buffer.from(JSON.stringify({
  sub: user.id,
  email: fields.email,
  role: fields.role || 'client',
  name: fields.name || fields.full_name || '',
  iat: Math.floor(Date.now() / 1000),
  exp: Math.floor(Date.now() / 1000) + (24 * 60 * 60)
})).toString('base64url');

const signature = crypto.createHmac('sha256', JWT_SECRET).update(header + '.' + payload).digest('base64url');
const token = header + '.' + payload + '.' + signature;

return [{
  json: {
    _auth_error: false,
    token,
    user: {
      id: user.id,
      name: fields.name || fields.full_name || '',
      email: fields.email,
      role: fields.role || 'client',
      onboardingComplete: true,
      plan: fields.plan || 'starter',
      createdAt: fields.created_at || user.createdTime
    }
  }
}];
